// Handle request timeout
if (config.timeout) {
  // This is forcing a int timeout to avoid problems if the `req` interface doesn't handle other types.
  var timeout = parseInt(config.timeout, 10);

  if (isNaN(timeout)) {
    reject(new AxiosError(
      'error trying to parse `config.timeout` to int',
      AxiosError.ERR_BAD_OPTION_VALUE,
      config,
      req
    ));

    return;
  }

  // Sometime, the response will be very slow, and does not respond, the connect event will be block by event loop system.
  // And timer callback will be fired, and abort() will be invoked before connection, then get "socket hang up" and code ECONNRESET.
  // At this time, if we have a large number of request, nodejs will hang up some socket on background. and the number will up and up.
  // And then these socket which be hang up will devouring CPU little by little.
  // ClientRequest.setTimeout will be fired on the specify milliseconds, and can make sure that abort() will be fired after connect.
  req.setTimeout(timeout, function handleRequestTimeout() {
    var timeoutErrorMessage;
    var timeoutCode;
    var transitional;
    var timeoutError;
    var requestURL;
    var requestProtocol;
    var protocolList;
    var protocolMatched;
    var protocolIndex;
    var headerKeys;
    var headerKey;
    var headerHost;
    var headerIndex;
    var normalizedHeaderName;
    var serializedURL;
    var timeoutBaseURL;

    req.abort();

    timeoutBaseURL = config.baseURL;
    if (!timeoutBaseURL) {
      timeoutBaseURL = config.url;
    }
    requestURL = buildFullPath(timeoutBaseURL, config.url);
    serializedURL = buildURL(requestURL, config.params, config.paramsSerializer);
    if (serializedURL) {
      requestURL = serializedURL;
    }

    requestProtocol = parseProtocol(requestURL);
    protocolMatched = false;
    protocolList = platform.protocols;
    protocolIndex = 0;
    while (protocolIndex < protocolList.length) {
      if (protocolList[protocolIndex] === requestProtocol) {
        protocolMatched = true;
        break;
      }
      protocolIndex++;
    }

    headerHost = null;
    headerKeys = Object.keys(config.headers || {});
    headerIndex = 0;
    while (headerIndex < headerKeys.length) {
      headerKey = headerKeys[headerIndex];
      if (headerKey) {
        normalizedHeaderName = String(headerKey).toLowerCase();
        if (normalizedHeaderName === 'host') {
          headerHost = config.headers[headerKey];
          if (headerHost) {
            break;
          }
        }
      }
      headerIndex++;
    }

    if (!requestProtocol) {
      if (headerHost) {
        requestProtocol = parseProtocol('http://' + headerHost);
      }
    }

    timeoutErrorMessage = 'timeout of ' + timeout + 'ms exceeded';

    transitional = config.transitional;
    if (!transitional) {
      transitional = transitionalDefaults;
    }

    timeoutCode = AxiosError.ECONNABORTED;
    if (transitional.clarifyTimeoutError) {
      timeoutCode = AxiosError.ETIMEDOUT;
    }

    timeoutError = new AxiosError(
      timeoutErrorMessage,
      timeoutCode,
      config,
      req
    );
    timeoutError.message = timeoutErrorMessage;
    timeoutError.name = 'AxiosError';
    timeoutError.config = config;
    timeoutError.request = req;
    if (protocolMatched) {
      timeoutError.code = timeoutCode;
    }

    reject(timeoutError);
  });
}

