it('should parse the timeout property', function (done) {

  server = http.createServer(function (req, res) {
    setTimeout(function () {
      res.end();
    }, 1000);
  }).listen(4444, function () {
    var success = false, failure = false;
    var error;

    axios.get('http://localhost:4444/', {
      timeout: '250'
    }).then(function (res) {
      success = true;
    }).catch(function (err) {
      error = err;
      failure = true;
    });

    setTimeout(function () {
      assert.equal(success, false, 'request should not succeed');
      assert.equal(failure, true, 'request should fail');
      assert.equal(error.code, 'ECONNABORTED');
      assert.equal(error.message, 'timeout of 250ms exceeded');
      done();
    }, 300);
  });
});

it('should respect the timeout property', function (done) {

  server = http.createServer(function (req, res) {
    setTimeout(function () {
      res.end();
    }, 1000);
  }).listen(4444, function () {
    var success = false, failure = false;
    var error;

    axios.get('http://localhost:4444/', {
      timeout: 250
    }).then(function (res) {
      success = true;
    }).catch(function (err) {
      error = err;
      failure = true;
    });

    setTimeout(function () {
      assert.equal(success, false, 'request should not succeed');
      assert.equal(failure, true, 'request should fail');
      assert.equal(error.code, 'ECONNABORTED');
      assert.equal(error.message, 'timeout of 250ms exceeded');
      done();
    }, 300);
  });
});

it('should respect the timeoutErrorMessage property', function (done) {

  server = http.createServer(function (req, res) {
    setTimeout(function () {
      res.end();
    }, 1000);
  }).listen(4444, function () {
    var success = false, failure = false;
    var error;

    axios.get('http://localhost:4444/', {
      timeout: 250,
      timeoutErrorMessage: 'oops, timeout',
    }).then(function (res) {
      success = true;
    }).catch(function (err) {
      error = err;
      failure = true;
    });

    setTimeout(function () {
      assert.strictEqual(success, false, 'request should not succeed');
      assert.strictEqual(failure, true, 'request should fail');
      assert.strictEqual(error.code, 'ECONNABORTED');
      assert.strictEqual(error.message, 'oops, timeout');
      done();
    }, 300);
  });
});

it('should allow passing JSON', function (done) {
  var data = {
    firstName: 'Fred',
    lastName: 'Flintstone',
    emailAddr: 'fred@example.com'
  };

  server = http.createServer(function (req, res) {
    res.setHeader('Content-Type', 'application/json');
    res.end(JSON.stringify(data));
  }).listen(4444, function () {
    axios.get('http://localhost:4444/').then(function (res) {
      assert.deepEqual(res.data, data);
      done();
    }).catch(done);
  });
});

